mapper.sql:
FROM quasar_tracing.spans
WHERE Timestamp BETWEEN fromUnixTimestamp64Milli(#{from}) AND fromUnixTimestamp64Milli(#{to})
GROUP BY TraceId
HAVING 1 = 1

    AND has(groupUniqArray(ServiceName), #{service})


    AND argMin(SpanName, Timestamp) = #{operation}


    AND countIf(StatusCode = 'Error') > 0


    AND countIf(StatusCode = 'Error') = 0


    AND any(ResourceAttributes['deployment.environment.name']) = #{environment}


    AND (
        any(ResourceAttributes['service.namespace']) = #{namespace}
        OR if(indexOf(mapKeys(any(ResourceAttributes)), 'k8s.namespace.name') = 0, '',
            arrayElement(mapValues(any(ResourceAttributes)), indexOf(mapKeys(any(ResourceAttributes)), 'k8s.namespace.name'))) = #{namespace}
    )


    AND if(indexOf(mapKeys(any(ResourceAttributes)), 'k8s.namespace.name') = 0, '',
        arrayElement(mapValues(any(ResourceAttributes)), indexOf(mapKeys(any(ResourceAttributes)), 'k8s.namespace.name'))) = #{k8sNamespace}


    AND if(indexOf(mapKeys(any(ResourceAttributes)), 'k8s.pod.name') = 0, '',
        arrayElement(mapValues(any(ResourceAttributes)), indexOf(mapKeys(any(ResourceAttributes)), 'k8s.pod.name'))) = #{k8sPodName}


    AND if(indexOf(mapKeys(any(ResourceAttributes)), 'k8s.node.name') = 0, '',
        arrayElement(mapValues(any(ResourceAttributes)), indexOf(mapKeys(any(ResourceAttributes)), 'k8s.node.name'))) = #{k8sNodeName}


    AND if(indexOf(mapKeys(any(ResourceAttributes)), 'service.instance.id') = 0, '',
        arrayElement(mapValues(any(ResourceAttributes)), indexOf(mapKeys(any(ResourceAttributes)), 'service.instance.id'))) = #{serviceInstanceId}


    AND (max(toUnixTimestamp64Nano(Timestamp) + Duration) - min(toUnixTimestamp64Nano(Timestamp))) >= #{minDurationNs}


    AND (max(toUnixTimestamp64Nano(Timestamp) + Duration) - min(toUnixTimestamp64Nano(Timestamp))) <= #{maxDurationNs}


    AND (positionCaseInsensitive(argMin(SpanName, Timestamp), #{q}) > 0 OR position(TraceId, #{q}) > 0)
